insert into public.events (slug, title, tagline, category, start_at, end_at, date_label, time_label, venue, collab, banner, trailer, featured, registration, description, highlights, sessions, gallery, gallery_title) values
  ('orientation-26', 'ORIENTATION''26', 'Your journey with <Code/Forge> starts here.', 'Induction', '2026-11-20T16:00:00+05:30', null, '20 Nov 2026', '4:00 PM', 'NIAMT Auditorium', null, '/media/orientation26-poster.jpg', '/media/orientation26-trailer.mp4', true, true, 'The official orientation of Code Forge for the new batch. Meet the team and the mentors, discover our communities — Software Development, AI & Data Science, Cybersecurity & Blockchain, Electronics & Automation and the Media Cell — and see what you can build with us this year.', array['Meet the core team, community leads & faculty advisors', 'Walkthrough of every Code Forge community and how to join', 'What''s coming up: workshops, ForgeX Week, contests & hackathons', 'Q&A — ask us anything about coding, clubs and careers']::text[], '[]'::jsonb, '{}'::text[], null),
  ('devfest-prehype-26', 'DevFest 2026 On-Campus Pre-Hype', null, 'Community', '2026-10-10T14:00:00+05:30', null, '10 Oct 2026', '2:00 PM onwards', 'Red Building (Lecture Hall)', 'GDG Ranchi', '/events/devfest-prehype-26/01.webp', null, false, false, 'Code Forge, in collaboration with GDG Ranchi, organised the DevFest 2026 on-campus pre-hype event. The session introduced students to Google Developer Groups, their community initiatives and the significance of DevFest in the technology ecosystem — with networking, skill-building and career opportunities through developer events.', array['Introduction to GDG and its developer community', 'Insights into DevFest 2026 and careers in tech', 'Interactive tech quizzes, games and activities', 'Competitions with official GDG swags & goodies for winners', 'Participation from students across all years']::text[], '[]'::jsonb, '{}'::text[], null),
  ('frontend-sprint', 'Frontend Development Sprint', null, 'Competition', '2026-08-25T17:30:00+05:30', null, '25 Aug 2026', '5:30 PM – 8:00 PM', 'LHC 107', null, '/events/frontend-sprint/01.webp', null, false, false, 'A time-bound practice challenge where teams of three designed and built attractive, responsive and interactive websites with HTML, CSS and JavaScript — encouraging creativity, problem solving, healthy competition and hands-on learning.', array['Team challenge (teams of 3)', 'HTML, CSS & JavaScript', 'Projects built by the fresher batch']::text[], '[]'::jsonb, array['/events/frontend-sprint/02.webp', '/events/frontend-sprint/03.webp', '/events/frontend-sprint/04.webp', '/events/frontend-sprint/05.webp', '/events/frontend-sprint/06.webp']::text[], 'Projects made by the fresher batch'),
  ('finance-webinar', 'Finance Webinar by Fin Maverick', null, 'Session', '2026-08-17T18:00:00+05:30', null, '17 Aug 2026', null, 'Online (Google Meet)', 'Fin Maverick', null, null, false, false, '“Beyond the Classroom: Building a Career in Finance” — a webinar on career paths and industry expectations across Investment Banking, Equity Research, Venture Capital, Private Equity, Corporate Finance, Financial Markets and FinTech, followed by an online case-study competition on the Fin Maverick platform.', array['Insights into finance careers and industry expectations', 'Hands-on financial case analysis and problem solving', 'Digital certificates for participants, recognition for top performers', 'Complimentary Technical Analysis course access for attendees']::text[], '[]'::jsonb, '{}'::text[], null),
  ('n8n-automation', 'n8n Automation Session', null, 'Workshop', '2026-04-18T14:15:00+05:30', null, '18 Apr 2026', '2:15 PM – 4:00 PM', 'ITnC Lab', null, '/events/n8n-automation/01.webp', null, false, false, 'An introduction to no-code workflow automation with n8n: how WhatsApp chatbots work, how apps talk to each other through APIs, and how emails, notifications and routine tasks can be automated — ending with a live demo of building a first workflow.', array['How WhatsApp chatbots work', 'APIs and app-to-app communication', 'Automating emails & notifications', 'Live: build your first workflow']::text[], '[]'::jsonb, '{}'::text[], null),
  ('riot-robotics', 'Robotics Workshop by R.I.O.T', null, 'Workshop', '2026-03-23T15:00:00+05:30', null, '23 Mar 2026', '3:00 PM onwards', 'Admin Building, 2nd Floor', 'R.I.O.T — Robotics & IoT Wing, IIIT Ranchi', '/events/riot-robotics/01.webp', null, false, false, 'R.I.O.T, the Robotics & IoT wing of IIIT Ranchi, ran a hands-on robotics workshop at NIAMT with live robot demonstrations, an RC plane showcase and an interactive session on robot components, construction and programming — and introduced YANTRA, the robotics fest at IIIT Ranchi.', array['Live robot demonstrations', 'RC plane showcase', 'Robot components, build & programming', 'Outreach for YANTRA robotics fest']::text[], '[]'::jsonb, '{}'::text[], null),
  ('js-webdev', 'Introduction to JS & WebDev', null, 'Workshop', '2026-02-24T17:30:00+05:30', '2026-02-26T19:30:00+05:30', '24 – 26 Feb 2026', '5:30 PM', 'ITnC Lab', null, '/events/js-webdev/01.webp', null, false, false, 'A beginner-friendly, three-day hands-on workshop to kick-start web development — from a complete roadmap to HTML/CSS fundamentals, JavaScript basics and DOM concepts with a mini project.', array['Complete web development roadmap', 'HTML & CSS fundamentals', 'JavaScript basics', 'DOM concepts & mini project']::text[], '[]'::jsonb, '{}'::text[], null),
  ('intro-llms', 'Introduction to LLMs', null, 'Session', '2026-02-21T11:00:00+05:30', null, '21 Feb 2026', '11:00 AM', 'ITnC Lab', null, '/events/intro-llms/01.webp', null, false, false, 'Ever wondered how ChatGPT actually works? This session broke down Large Language Models — transformers and attention, how LLMs are trained, and where they are used in the real world.', array['What are Large Language Models?', 'Transformers & the attention mechanism', 'How LLMs are trained', 'Real-world applications']::text[], '[]'::jsonb, '{}'::text[], null),
  ('forgex-league', 'ForgeX League by Matiks', null, 'Competition', '2026-02-15T00:00:00+05:30', '2026-02-21T23:59:00+05:30', '15 – 21 Feb 2026', null, 'Online — play anywhere', 'Matiks', '/events/forgex-league/01.webp', null, false, false, 'A week-long challenge where speed meets strategy: compete, earn XP, climb the leaderboard and prove your problem-solving skills — solo or with friends.', array['Prizes worth ₹3K – ₹10K+', 'Exclusive Matiks T-shirts for winners', 'Play anytime, anywhere']::text[], '[]'::jsonb, '{}'::text[], null),
  ('forgex-week', 'ForgeX Week', null, 'Workshop', '2026-01-27T17:30:00+05:30', '2026-02-03T19:00:00+05:30', '27 Jan – 03 Feb 2026', '5:30 PM', 'LHC 101 / LHC 103', null, '/events/forgex-week/01.webp', null, false, false, 'Five sessions, five domains. ForgeX Week took students from open source to competitive programming, Arduino, AI/ML and cybersecurity — one hands-on session each day.', '{}'::text[], '[{"day":"Day 1","title":"Introduction to Git & GitHub","date":"27 Jan","venue":"LHC 101","note":"Open source, pull requests, issues — and making your first contribution."},{"day":"Day 2","title":"Introduction to Competitive Programming","date":"28 Jan","venue":"LHC 103","note":"CP mindset, time & space complexity, STL and live problem solving."},{"day":"Day 3","title":"Workshop on Arduino Programming","date":"29 Jan","venue":"LHC 103","note":"What Arduino is, prototyping and the Arduino ecosystem."},{"day":"Day 4","title":"Introduction to AI & ML","date":"02 Feb","venue":"LHC 103","note":"AI vs ML vs DL vs GenAI, ML techniques and careers in AI."},{"day":"Day 5","title":"Introduction to Cybersecurity","date":"03 Feb","venue":"LHC 103","note":"Cyber threats, malware, passwords and authentication basics."}]'::jsonb, array['/events/forgex-week/02.webp', '/events/forgex-week/03.webp', '/events/forgex-week/04.webp', '/events/forgex-week/05.webp', '/events/forgex-week/06.webp', '/events/forgex-week/07.webp', '/events/forgex-week/08.webp']::text[], null),
  ('induction-2026', 'Student Induction Programme 2026', null, 'Induction', '2026-01-21T17:00:00+05:30', null, '21 Jan 2026', '5:00 PM', 'Auditorium', null, '/events/induction-2026/01.webp', null, false, false, 'The Code Forge induction for the first-year batch of 2025–29, with faculty guidance, an introduction to every Code Forge community, the Code Forge Quiz Arena and an On-the-Spot challenge.', array['Faculty guidance', 'Introduction to the communities of Code Forge', 'Code Forge Quiz Arena', 'On-the-Spot Challenge']::text[], '[]'::jsonb, array['/events/induction-2026/02.webp', '/events/induction-2026/03.webp']::text[], null),
  ('sticker-contest', 'Sticker Making Contest', null, 'Competition', '2026-01-20T17:00:00+05:30', null, '20 Jan 2026', null, null, null, '/events/sticker-contest/banner.webp', null, false, false, 'A design contest to sharpen graphic-design skills with tools like Canva and Adobe Illustrator. Here are a few of the stickers our students made.', '{}'::text[], '[]'::jsonb, array['/events/sticker-contest/01.webp', '/events/sticker-contest/02.webp', '/events/sticker-contest/03.webp', '/events/sticker-contest/04.webp', '/events/sticker-contest/05.webp']::text[], 'Stickers made by NIAMT students'),
